file.content:
{
	"$schema": "https://schemas.wp.org/trunk/block.json",
	"apiVersion": 3,
	"name": "telex/countdown-timer",
	"version": "0.1.0",
	"title": "Countdown Timer",
	"category": "widgets",
	"icon": "clock",
	"description": "Display a countdown timer to a specific date and time with customizable styling and labels.",
	"example": {
		"attributes": {
			"targetDate": "2025-12-31T23:59:59",
			"showDays": true,
			"showHours": true,
			"showMinutes": true,
			"showSeconds": true
		}
	},
	"attributes": {
		"targetDate": {
			"type": "string",
			"default": ""
		},
		"showDays": {
			"type": "boolean",
			"default": true
		},
		"showHours": {
			"type": "boolean",
			"default": true
		},
		"showMinutes": {
			"type": "boolean",
			"default": true
		},
		"showSeconds": {
			"type": "boolean",
			"default": true
		},
		"labelDays": {
			"type": "string",
			"default": "Days"
		},
		"labelHours": {
			"type": "string",
			"default": "Hours"
		},
		"labelMinutes": {
			"type": "string",
			"default": "Minutes"
		},
		"labelSeconds": {
			"type": "string",
			"default": "Seconds"
		},
		"completionMessage": {
			"type": "string",
			"default": "The countdown has ended!"
		},
		"numberColor": {
			"type": "string",
			"default": "#000000"
		},
		"labelColor": {
			"type": "string",
			"default": "#666666"
		},
		"numberFontSize": {
			"type": "number",
			"default": 48
		},
		"labelFontSize": {
			"type": "number",
			"default": 14
		},
		"alignment": {
			"type": "string",
			"default": "center"
		}
	},
	"supports": {
		"html": false,
		"align": true,
		"color": {
			"background": true,
			"text": false
		},
		"spacing": {
			"padding": true,
			"margin": true
		}
	},
	"textdomain": "countdown-timer",
	"editorScript": "file:./index.js",
	"editorStyle": "file:./index.css",
	"style": "file:./style-index.css",
	"viewScript": "file:./view.js"
}

/**
 * Registers a new block provided a unique name and an object defining its behavior.
 *
 * @see https://developer.wordpress.org/block-editor/reference-guides/block-api/block-registration/
 */
import { registerBlockType } from '@wordpress/blocks';

/**
 * Lets webpack process CSS, SASS or SCSS files referenced in JavaScript files.
 * All files containing `style` keyword are bundled together. The code used
 * gets applied both to the front of your site and to the editor.
 *
 * @see https://www.npmjs.com/package/@wordpress/scripts#using-css
 */
import './style.scss';

/**
 * Internal dependencies
 */
import Edit from './edit';
import save from './save';
import metadata from './block.json';

/**
 * Every block starts by registering a new block type definition.
 *
 * @see https://developer.wordpress.org/block-editor/reference-guides/block-api/block-registration/
 */
registerBlockType( metadata.name, {
	/**
	 * @see ./edit.js
	 */
	edit: Edit,

	/**
	 * @see ./save.js
	 */
	save,
} );

/**
 * Retrieves the translation of text.
 *
 * @see https://developer.wordpress.org/block-editor/reference-guides/packages/packages-i18n/
 */
import { __ } from '@wordpress/i18n';

/**
 * React hook that is used to mark the block wrapper element.
 * It provides all the necessary props like the class name.
 *
 * @see https://developer.wordpress.org/block-editor/reference-guides/packages/packages-block-editor/#useblockprops
 */
import { 
	useBlockProps, 
	InspectorControls,
	BlockControls,
	AlignmentToolbar
} from '@wordpress/block-editor';

import {
	PanelBody,
	ToggleControl,
	TextControl,
	RangeControl,
	DateTimePicker,
	ToolbarButton,
	ColorPalette,
	Popover
} from '@wordpress/components';

import { useState, useEffect } from '@wordpress/element';
import { calendar } from '@wordpress/icons';

/**
 * Lets webpack process CSS, SASS or SCSS files referenced in JavaScript files.
 * Those files can contain any CSS code that gets applied to the editor.
 *
 * @see https://www.npmjs.com/package/@wordpress/scripts#using-css
 */
import './editor.scss';

/**
 * Calculate time remaining
 */
function calculateTimeRemaining( targetDate ) {
	if ( ! targetDate ) {
		return null;
	}

	const now = new Date().getTime();
	const target = new Date( targetDate ).getTime();
	const difference = target - now;

	if ( difference <= 0 ) {
		return {
			days: 0,
			hours: 0,
			minutes: 0,
			seconds: 0,
			isExpired: true
		};
	}

	const days = Math.floor( difference / ( 1000 * 60 * 60 * 24 ) );
	const hours = Math.floor( ( difference % ( 1000 * 60 * 60 * 24 ) ) / ( 1000 * 60 * 60 ) );
	const minutes = Math.floor( ( difference % ( 1000 * 60 * 60 ) ) / ( 1000 * 60 ) );
	const seconds = Math.floor( ( difference % ( 1000 * 60 ) ) / 1000 );

	return {
		days,
		hours,
		minutes,
		seconds,
		isExpired: false
	};
}

/**
 * The edit function describes the structure of your block in the context of the
 * editor. This represents what the editor will render when the block is used.
 *
 * @see https://developer.wordpress.org/block-editor/reference-guides/block-api/block-edit-save/#edit
 *
 * @return {Element} Element to render.
 */
export default function Edit( { attributes, setAttributes } ) {
	const {
		targetDate,
		showDays,
		showHours,
		showMinutes,
		showSeconds,
		labelDays,
		labelHours,
		labelMinutes,
		labelSeconds,
		completionMessage,
		numberColor,
		labelColor,
		numberFontSize,
		labelFontSize,
		alignment
	} = attributes;

	const [ timeRemaining, setTimeRemaining ] = useState( calculateTimeRemaining( targetDate ) );
	const [ showDatePicker, setShowDatePicker ] = useState( false );

	// Update countdown every second in the editor
	useEffect( () => {
		const timer = setInterval( () => {
			setTimeRemaining( calculateTimeRemaining( targetDate ) );
		}, 1000 );

		return () => clearInterval( timer );
	}, [ targetDate ] );

	const blockProps = useBlockProps( {
		style: {
			textAlign: alignment
		}
	} );

	const colors = [
		{ name: 'Black', color: '#000000' },
		{ name: 'White', color: '#ffffff' },
		{ name: 'Red', color: '#ff0000' },
		{ name: 'Green', color: '#00ff00' },
		{ name: 'Blue', color: '#0000ff' },
		{ name: 'Gray', color: '#666666' },
	];

	return (
		<>
			<BlockControls>
				<AlignmentToolbar
					value={ alignment }
					onChange={ ( newAlignment ) => setAttributes( { alignment: newAlignment } ) }
				/>
				<ToolbarButton
					icon={ calendar }
					label={ __( 'Set Date & Time', 'countdown-timer' ) }
					onClick={ () => setShowDatePicker( ! showDatePicker ) }
				/>
				{ showDatePicker && (
					<Popover
						position="bottom center"
						onClose={ () => setShowDatePicker( false ) }
					>
						<div style={ { padding: '16px' } }>
							<DateTimePicker
								currentDate={ targetDate || new Date().toISOString() }
								onChange={ ( newDate ) => setAttributes( { targetDate: newDate } ) }
								is12Hour={ true }
							/>
						</div>
					</Popover>
				) }
			</BlockControls>

			<InspectorControls>
				<PanelBody title={ __( 'Countdown Settings', 'countdown-timer' ) }>
					<div style={ { marginBottom: '16px' } }>
						<strong>{ __( 'Target Date & Time', 'countdown-timer' ) }</strong>
						<DateTimePicker
							currentDate={ targetDate || new Date().toISOString() }
							onChange={ ( newDate ) => setAttributes( { targetDate: newDate } ) }
							is12Hour={ true }
						/>
					</div>
				</PanelBody>

				<PanelBody title={ __( 'Display Units', 'countdown-timer' ) }>
					<ToggleControl
						label={ __( 'Show Days', 'countdown-timer' ) }
						checked={ showDays }
						onChange={ ( value ) => setAttributes( { showDays: value } ) }
					/>
					<ToggleControl
						label={ __( 'Show Hours', 'countdown-timer' ) }
						checked={ showHours }
						onChange={ ( value ) => setAttributes( { showHours: value } ) }
					/>
					<ToggleControl
						label={ __( 'Show Minutes', 'countdown-timer' ) }
						checked={ showMinutes }
						onChange={ ( value ) => setAttributes( { showMinutes: value } ) }
					/>
					<ToggleControl
						label={ __( 'Show Seconds', 'countdown-timer' ) }
						checked={ showSeconds }
						onChange={ ( value ) => setAttributes( { showSeconds: value } ) }
					/>
				</PanelBody>

				<PanelBody title={ __( 'Labels', 'countdown-timer' ) } initialOpen={ false }>
					<TextControl
						label={ __( 'Days Label', 'countdown-timer' ) }
						value={ labelDays }
						onChange={ ( value ) => setAttributes( { labelDays: value } ) }
					/>
					<TextControl
						label={ __( 'Hours Label', 'countdown-timer' ) }
						value={ labelHours }
						onChange={ ( value ) => setAttributes( { labelHours: value } ) }
					/>
					<TextControl
						label={ __( 'Minutes Label', 'countdown-timer' ) }
						value={ labelMinutes }
						onChange={ ( value ) => setAttributes( { labelMinutes: value } ) }
					/>
					<TextControl
						label={ __( 'Seconds Label', 'countdown-timer' ) }
						value={ labelSeconds }
						onChange={ ( value ) => setAttributes( { labelSeconds: value } ) }
					/>
				</PanelBody>

				<PanelBody title={ __( 'Completion Message', 'countdown-timer' ) } initialOpen={ false }>
					<TextControl
						label={ __( 'Message', 'countdown-timer' ) }
						value={ completionMessage }
						onChange={ ( value ) => setAttributes( { completionMessage: value } ) }
						help={ __( 'This message will be displayed when the countdown reaches zero.', 'countdown-timer' ) }
					/>
				</PanelBody>

				<PanelBody title={ __( 'Typography', 'countdown-timer' ) } initialOpen={ false }>
					<RangeControl
						label={ __( 'Number Font Size', 'countdown-timer' ) }
						value={ numberFontSize }
						onChange={ ( value ) => setAttributes( { numberFontSize: value } ) }
						min={ 16 }
						max={ 120 }
					/>
					<RangeControl
						label={ __( 'Label Font Size', 'countdown-timer' ) }
						value={ labelFontSize }
						onChange={ ( value ) => setAttributes( { labelFontSize: value } ) }
						min={ 10 }
						max={ 32 }
					/>
				</PanelBody>

				<PanelBody title={ __( 'Colors', 'countdown-timer' ) } initialOpen={ false }>
					<div style={ { marginBottom: '16px' } }>
						<strong>{ __( 'Number Color', 'countdown-timer' ) }</strong>
						<ColorPalette
							colors={ colors }
							value={ numberColor }
							onChange={ ( value ) => setAttributes( { numberColor: value } ) }
						/>
					</div>
					<div>
						<strong>{ __( 'Label Color', 'countdown-timer' ) }</strong>
						<ColorPalette
							colors={ colors }
							value={ labelColor }
							onChange={ ( value ) => setAttributes( { labelColor: value } ) }
						/>
					</div>
				</PanelBody>
			</InspectorControls>

			<div { ...blockProps }>
				{ ! targetDate ? (
					<div className="countdown-timer-placeholder">
						<p>{ __( 'Click the calendar icon in the toolbar to set a countdown date.', 'countdown-timer' ) }</p>
					</div>
				) : timeRemaining && timeRemaining.isExpired ? (
					<div 
						className="countdown-timer-completion"
						style={ {
							fontSize: `${ numberFontSize }px`,
							color: numberColor
						} }
					>
						{ completionMessage }
					</div>
				) : timeRemaining ? (
					<div className="countdown-timer-display">
						{ showDays && (
							<div className="countdown-timer-unit">
								<div 
									className="countdown-timer-number"
									style={ {
										fontSize: `${ numberFontSize }px`,
										color: numberColor
									} }
								>
									{ String( timeRemaining.days ).padStart( 2, '0' ) }
								</div>
								<div 
									className="countdown-timer-label"
									style={ {
										fontSize: `${ labelFontSize }px`,
										color: labelColor
									} }
								>
									{ labelDays }
								</div>
							</div>
						) }
						{ showHours && (
							<div className="countdown-timer-unit">
								<div 
									className="countdown-timer-number"
									style={ {
										fontSize: `${ numberFontSize }px`,
										color: numberColor
									} }
								>
									{ String( timeRemaining.hours ).padStart( 2, '0' ) }
								</div>
								<div 
									className="countdown-timer-label"
									style={ {
										fontSize: `${ labelFontSize }px`,
										color: labelColor
									} }
								>
									{ labelHours }
								</div>
							</div>
						) }
						{ showMinutes && (
							<div className="countdown-timer-unit">
								<div 
									className="countdown-timer-number"
									style={ {
										fontSize: `${ numberFontSize }px`,
										color: numberColor
									} }
								>
									{ String( timeRemaining.minutes ).padStart( 2, '0' ) }
								</div>
								<div 
									className="countdown-timer-label"
									style={ {
										fontSize: `${ labelFontSize }px`,
										color: labelColor
									} }
								>
									{ labelMinutes }
								</div>
							</div>
						) }
						{ showSeconds && (
							<div className="countdown-timer-unit">
								<div 
									className="countdown-timer-number"
									style={ {
										fontSize: `${ numberFontSize }px`,
										color: numberColor
									} }
								>
									{ String( timeRemaining.seconds ).padStart( 2, '0' ) }
								</div>
								<div 
									className="countdown-timer-label"
									style={ {
										fontSize: `${ labelFontSize }px`,
										color: labelColor
									} }
								>
									{ labelSeconds }
								</div>
							</div>
						) }
					</div>
				) : null }
			</div>
		</>
	);
}

/**
 * The following styles get applied both on the front of your site
 * and in the editor.
 */

.wp-block-telex-countdown-timer {
	padding: 20px;
}

.countdown-timer-display {
	display: flex;
	flex-wrap: wrap;
	gap: 20px;
	justify-content: center;
	align-items: center;
}

.countdown-timer-unit {
	display: flex;
	flex-direction: column;
	align-items: center;
	gap: 8px;
	min-width: 80px;
}

.countdown-timer-number {
	font-weight: bold;
	line-height: 1;
	font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Oxygen-Sans, Ubuntu, Cantarell, "Helvetica Neue", sans-serif;
}

.countdown-timer-label {
	text-transform: uppercase;
	letter-spacing: 1px;
	font-weight: 500;
	line-height: 1;
}

.countdown-timer-completion {
	font-weight: bold;
	padding: 20px;
	text-align: center;
}

.countdown-timer-placeholder {
	padding: 40px;
	text-align: center;
	background: #f0f0f0;
	border: 2px dashed #ccc;
	border-radius: 4px;

	p {
		margin: 0;
		color: #666;
	}
}

/* Responsive adjustments */
@media (max-width: 768px) {
	.countdown-timer-display {
		gap: 15px;
	}

	.countdown-timer-unit {
		min-width: 60px;
	}
}

/**
 * The following styles get applied inside the editor only.
 */

.wp-block-telex-countdown-timer {
	.countdown-timer-placeholder {
		background: #f9f9f9;
		border: 2px dashed #ddd;

		&:hover {
			border-color: #999;
		}
	}
}

/**
 * Frontend JavaScript for the Countdown Timer block
 * Handles real-time countdown updates
 */

document.addEventListener( 'DOMContentLoaded', function() {
	const countdownBlocks = document.querySelectorAll( '.wp-block-telex-countdown-timer' );

	countdownBlocks.forEach( function( block ) {
		const targetDate = block.getAttribute( 'data-target-date' );
		const showDays = block.getAttribute( 'data-show-days' ) === 'true';
		const showHours = block.getAttribute( 'data-show-hours' ) === 'true';
		const showMinutes = block.getAttribute( 'data-show-minutes' ) === 'true';
		const showSeconds = block.getAttribute( 'data-show-seconds' ) === 'true';
		const labelDays = block.getAttribute( 'data-label-days' );
		const labelHours = block.getAttribute( 'data-label-hours' );
		const labelMinutes = block.getAttribute( 'data-label-minutes' );
		const labelSeconds = block.getAttribute( 'data-label-seconds' );
		const completionMessage = block.getAttribute( 'data-completion-message' );
		const numberColor = block.getAttribute( 'data-number-color' );
		const labelColor = block.getAttribute( 'data-label-color' );
		const numberFontSize = block.getAttribute( 'data-number-font-size' );
		const labelFontSize = block.getAttribute( 'data-label-font-size' );

		const displayElement = block.querySelector( '.countdown-timer-display' );

		if ( ! targetDate || ! displayElement ) {
			return;
		}

		function calculateTimeRemaining() {
			const now = new Date().getTime();
			const target = new Date( targetDate ).getTime();
			const difference = target - now;

			if ( difference <= 0 ) {
				return {
					days: 0,
					hours: 0,
					minutes: 0,
					seconds: 0,
					isExpired: true
				};
			}

			const days = Math.floor( difference / ( 1000 * 60 * 60 * 24 ) );
			const hours = Math.floor( ( difference % ( 1000 * 60 * 60 * 24 ) ) / ( 1000 * 60 * 60 ) );
			const minutes = Math.floor( ( difference % ( 1000 * 60 * 60 ) ) / ( 1000 * 60 ) );
			const seconds = Math.floor( ( difference % ( 1000 * 60 ) ) / 1000 );

			return {
				days: days,
				hours: hours,
				minutes: minutes,
				seconds: seconds,
				isExpired: false
			};
		}

		function padZero( num ) {
			return String( num ).padStart( 2, '0' );
		}

		function updateCountdown() {
			const timeRemaining = calculateTimeRemaining();

			if ( timeRemaining.isExpired ) {
				displayElement.innerHTML = '<div class="countdown-timer-completion" style="font-size: ' + numberFontSize + 'px; color: ' + numberColor + ';">' + completionMessage + '</div>';
				return true; // Stop the timer
			}

			let html = '';

			if ( showDays ) {
				html += '<div class="countdown-timer-unit">';
				html += '<div class="countdown-timer-number" style="font-size: ' + numberFontSize + 'px; color: ' + numberColor + ';">' + padZero( timeRemaining.days ) + '</div>';
				html += '<div class="countdown-timer-label" style="font-size: ' + labelFontSize + 'px; color: ' + labelColor + ';">' + labelDays + '</div>';
				html += '</div>';
			}

			if ( showHours ) {
				html += '<div class="countdown-timer-unit">';
				html += '<div class="countdown-timer-number" style="font-size: ' + numberFontSize + 'px; color: ' + numberColor + ';">' + padZero( timeRemaining.hours ) + '</div>';
				html += '<div class="countdown-timer-label" style="font-size: ' + labelFontSize + 'px; color: ' + labelColor + ';">' + labelHours + '</div>';
				html += '</div>';
			}

			if ( showMinutes ) {
				html += '<div class="countdown-timer-unit">';
				html += '<div class="countdown-timer-number" style="font-size: ' + numberFontSize + 'px; color: ' + numberColor + ';">' + padZero( timeRemaining.minutes ) + '</div>';
				html += '<div class="countdown-timer-label" style="font-size: ' + labelFontSize + 'px; color: ' + labelColor + ';">' + labelMinutes + '</div>';
				html += '</div>';
			}

			if ( showSeconds ) {
				html += '<div class="countdown-timer-unit">';
				html += '<div class="countdown-timer-number" style="font-size: ' + numberFontSize + 'px; color: ' + numberColor + ';">' + padZero( timeRemaining.seconds ) + '</div>';
				html += '<div class="countdown-timer-label" style="font-size: ' + labelFontSize + 'px; color: ' + labelColor + ';">' + labelSeconds + '</div>';
				html += '</div>';
			}

			displayElement.innerHTML = html;
			return false; // Continue the timer
		}

		// Initial update
		const isExpired = updateCountdown();

		// Continue updating every second if not expired
		if ( ! isExpired ) {
			setInterval( function() {
				const expired = updateCountdown();
				if ( expired ) {
					clearInterval( this );
				}
			}, 1000 );
		}
	} );
} );

{
	"name": "countdown-timer",
	"version": "0.1.0",
	"description": "A beautiful and customizable countdown timer block that displays time remaining until a specified future date and time.",
	"author": "WordPress Telex",
	"license": "GPL-2.0-or-later",
	"main": "build/index.js",
	"scripts": {
		"build": "wp-scripts build",
		"format": "wp-scripts format",
		"lint:css": "wp-scripts lint-style",
		"lint:js": "wp-scripts lint-js",
		"packages-update": "wp-scripts packages-update",
		"plugin-zip": "wp-scripts plugin-zip",
		"start": "wp-scripts start"
	},
	"devDependencies": {
		"@wordpress/scripts": "^30.15.0"
	}
}
